package com.dpworld.fms.scheduling;
import com.dpworld.fms.domain.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import java.util.concurrent.*; import static org.junit.jupiter.api.Assertions.*;
class SchedulingTest { Asset asset(double energy,Availability availability){return new Asset(UUID.randomUUID(),"ITV-1",AssetType.ITV,new GeoPoint(25,55),0,0,AssetStatus.IDLE,availability,energy,0,0,null,null,Instant.now(),null,"d","t",MaintenanceStatus.SERVICEABLE,Set.of("TWISTLOCK"),VehicleEnvelope.unrestricted());} FleetJob job(){var j=new FleetJob(UUID.randomUUID(),"J",JobType.CONTAINER_TRANSPORT,10,"A","B",Set.of("TWISTLOCK"),Instant.now(),Instant.now().plusSeconds(300),"t");j.transition(JobStatus.VALIDATED,"t","ok");j.transition(JobStatus.SCHEDULED,"t","ok");return j;}
 @Test void selectsEligibleCandidateAndRejectsLowFuel(){var s=new CandidateScorer(new CandidateScorer.Weights(1,1,1,1,1,1,1,1),15);var low=new CandidateScorer.Candidate(asset(10),1,1,0,0),ok=new CandidateScorer.Candidate(asset(80),2,2,0,0);assertEquals(ok,s.select(job(),List.of(low,ok),Instant.now()).orElseThrow());assertTrue(s.select(job(),List.of(low),Instant.now()).isEmpty());}
 @Test void reservationIsAtomic() throws Exception {var r=new ResourceReservationService();var pool=Executors.newFixedThreadPool(8);var start=new CountDownLatch(1);var tasks=new ArrayList<Future<Boolean>>();for(int i=0;i<20;i++){var job=UUID.randomUUID();tasks.add(pool.submit(()->{start.await();return r.reserve("BAY-1",job,Duration.ofMinutes(1)).isPresent();}));}start.countDown();assertEquals(1,tasks.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count());pool.shutdown();}
}
